574		misownedPath := nodeFileHexPath(f.dir, "gappy")
575	
576		for _, tc := range []struct {
577			name string
578			args []string
579		}{
580			{"health", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9"}},
581			{"health with baseline", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9", "--missed-since-seq", "1"}},
582		} {
583			t.Run(tc.name, func(t *testing.T) {
584				out, errOut, code := health(t, f, tc.args...)
585				if code == 0 {
586					t.Fatalf("misowned file must fail the query, exit=0 stdout=%q", out)
587				}
588				if out != "" {
589					t.Errorf("no health result may be printed, stdout=%q", out)
590				}
591				for _, want := range []string{misownedPath, "record 1", `"gappy"`, `"mono"`} {
592					if !strings.Contains(errOut, want) {
593						t.Errorf("stderr must contain %s, got %q", want, errOut)
594					}
595				}
596			})
597		}
598	
599		out, errOut, code := runCLI(t, f.dir, "",
600			"heartbeat", "history", "--data-dir", f.dir, "--node", "gappy")
601		if code == 0 {
602			t.Fatalf("history of a misowned file must fail, exit=0 stdout=%q", out)
603		}
604		if out != "" {
605			t.Errorf("no history may be printed, stdout=%q", out)
606		}
607		if !strings.Contains(errOut, misownedPath) || !strings.Contains(errOut, `"mono"`) {
608			t.Errorf("history stderr must name the file and the foreign node, got %q", errOut)
609		}
610	
611		// A submit batch touching the misowned node is refused as a whole: no
612		// success line, no counts, and the first-time node in the batch is not
613		// created either.
614		batch := `[
615		  {"node":"gappy","seq":9,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":999,"missed":0},
616		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
617		]`
618		out, errOut, code = runCLI(t, f.dir, batch,
619			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
620		if code == 0 {
621			t.Errorf("submit touching a misowned node must fail non-zero; stdout=%q", out)
622		}
623		if strings.Contains(out, "submitted") {
624			t.Errorf("rejected batch must not print success or counts, stdout=%q", out)
625		}
626		if !strings.Contains(errOut, misownedPath) {
627			t.Errorf("submit stderr must name the misowned file, got %q", errOut)
628		}
629		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
630			t.Errorf("brand-new node file must not be created, stat err=%v", err)
631		}
632	
633		// The real owner of the copied records is unaffected.
634		out, _, code = health(t, f,
635			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
636		if code != 0 || !strings.Contains(out, "node=mono") {
637			t.Errorf("real owner must still query normally: code=%d out=%q", code, out)
